export function tokenize(source) {
  const lines = [];
  const rawLines = source.split(/\r?\n/);
  rawLines.forEach((text, i) => {
    const line = i + 1;
    const tokens = [];
    let i2 = 0;
    while (i2 < text.length) {
      const ch = text[i2];
      if (ch === '#') break;
      if (/\s/.test(ch)) { i2++; continue; }
      const start = i2;
      let val = '';
      while (i2 < text.length && !/\s/.test(text[i2]) && text[i2] !== '#') { val += text[i2]; i2++; }
      tokens.push({ value: val, line, column: start + 1 });
    }
    lines.push({ number: line, tokens });
  });
  return lines;
}
