```js
import * as THREE from 'three';
import { tokenize } from './lexer.js';

const COMMANDS = ['box', 'sphere', 'group', 'end', 'move', 'spin'];
const ARITY = { box: 3, sphere: 1, group: 0, end: 0, move: 3, spin: 1 };

export function compileScene(source) {
  const lines = tokenize(source);
  const errors = [];
  const declared = new Map();
  const transforms = [];

  const makeNode = (type, name) => ({ type, name: name ?? null, position: [0,0,0], rotationDeg: 0, children: [] });

  const root = makeNode('group');
  const stack = [{ node: root, line: 0 }];

  for (const { number: line, tokens } of lines) {
    if (tokens.length === 0) continue;
    const cmdTok = tokens[0];
    const cmd = cmdTok.value;
    if (!COMMANDS.includes(cmd)) {
      errors.push({ line, message: `unknown command '${cmd}'` });
      continue;
    }
    const args = tokens.slice(1);
    if (args.length !== ARITY[cmd]) {
      errors.push({ line, message: `'${cmd}' expects ${ARITY[cmd]} argument(s), got ${args.length}` });
      continue;
    }
    const parent = stack[stack.length - 1].node;

    if (cmd === 'end') {
      if (stack.length === 1) { errors.push({ line, message: "'end' without matching 'group'" }); continue; }
      stack.pop();
      continue;
    }
    if (cmd === 'group') {
      const name = args[0].value;
      if (declared.has(name)) { errors.push({ line, message: `duplicate name '${name}'` }); continue; }
      const node = makeNode('group', name);
      parent.children.push(node);
      declared.set(name, node);
      stack.push({ node, line });
      continue;
    }
    if (cmd === 'box' || cmd === 'sphere') {
      const name = args[0].value;
      if (declared.has(name)) { errors.push({ line, message: `duplicate name '${name}'` }); continue; }
      const nums = [];
      let bad = false;
      for (let k = 1; k < args.length; k++) {
        const n = Number(args[k].value);
        if (!Number.isFinite(n)) { errors.push({ line, message: `non-numeric argument '${args[k].value}' for '${cmd}'` }); bad = true; break; }
        nums.push(n);
      }
      if (bad) continue;
      const node = cmd === 'box'
        ? makeNode('box', name) : makeNode('sphere', name);
      if (cmd === 'box') node.size = nums; else node.radius = nums[0];
      parent.children.push(node);
      declared.set(name, node);
      continue;
    }
    // move / spin
    const name = args[0].value;
    const nums = [];
    let bad = false;
    for (let k = 1; k < args.length; k++) {
      const n = Number(args[k].value);
      if (!Number.isFinite(n)) { errors.push({ line, message: `non-numeric argument '${args[k].value}' for '${cmd}'` }); bad = true; break; }
      nums.push(n);
    }
    if (bad) continue;
    transforms.push({ kind: cmd, name, nums, line });
  }

  for (const g of stack.slice(1)) {
    errors.push({ line: g.line, message: `unclosed group '${g.node.name}'` });
  }

  for (const t of transforms) {
    const node = declared.get(t.name);
    if (!node) { errors.push({ line: t.line, message: `${t.kind} on undeclared name '${t.name}'` }); continue; }
    if (t.kind === 'move') node.position = t.nums;
    else node.rotationDeg = t.nums[0];
  }

  attachObjects(root);

  return { root, errors };
}

function attachObjects(node) {
  let object;
  if (node.type === 'group') object = new THREE.Group();
  else if (node.type === 'box') object = new THREE.Mesh(new THREE.BoxGeometry(...node.size));
  else object = new THREE.Mesh(new THREE.SphereGeometry(node.radius, 32, 32));
  object.name = node.name ?? '';
  object.position.set(...node.position);
  object.rotation.y = THREE.MathUtils.degToRad(node.rotationDeg);
  node.object = object;
  if (node.type === 'group') for (const c of node.children) { attachObjects(c); object.add(c.object); }
  return node;
}
```

