const fmt = (n) => (Number.isInteger(n) ? String(n) : String(Number(n.toFixed(6))));

function printNode(node, indent, out) {
  const pad = '  '.repeat(indent);
  if (node.type === 'group') {
    out.push(`${pad}group ${node.name}`);
    for (const c of node.children) printNode(c, indent + 1, out);
    out.push(`${pad}end`);
    return;
  }
  if (node.type === 'box') out.push(`${pad}box ${node.name} ${node.size.map(fmt).join(' ')}`);
  else out.push(`${pad}sphere ${node.name} ${fmt(node.radius)}`);
  emitTransforms(node, pad, out);
}

function emitTransforms(node, pad, out) {
  const [x, y, z] = node.position;
  if (x !== 0 || y !== 0 || z !== 0) out.push(`${pad}move ${node.name} ${fmt(x)} ${fmt(y)} ${fmt(z)}`);
  if (node.rotationDeg !== 0) out.push(`${pad}spin ${node.name} ${fmt(node.rotationDeg)}`);
}

export function prettyPrint(root) {
  const out = [];
  for (const c of root.children) printNode(c, 0, out);
  return out.join('\n') + '\n';
}
