 * Tokenizer for the scene-description DSL.
 *
 * One statement per line. '#' starts a comment that runs to end of line.
 * Blank lines and comment-only lines yield no tokens but still occupy a
 * slot in the output so line numbers stay faithful to the source.
 *
 * Each token carries { value, line, column } (both 1-indexed).
 *
 * @param {string} source
 * @returns {Array<{number: number, text: string, tokens: Array<{value: string, line: number, column: number}>}>}
 */
export function tokenize(source) {
  const rawLines = String(source).split(/\r\n?|\n/);
  return rawLines.map((text, idx) => {
    const line = idx + 1;
    const tokens = [];
    let i = 0;
    while (i < text.length) {
      const ch = text[i];
      if (ch === '#') break; // rest of line is a comment
      if (/\s/.test(ch)) {
        i++;
        continue;
      }
      const start = i;
      while (i < text.length && !/\s/.test(text[i]) && text[i] !== '#') i++;
      tokens.push({ value: text.slice(start, i), line, column: start + 1 });
    }
    return { number: line, text, tokens };
  });
}
