import { tokenize } from './lexer.js';

/**
 * Scene DSL grammar (one statement per line):
 *
 *   box    <name> <w> <h> <d>
 *   sphere <name> <r>
 *   group  <name>
 *   end
 *   move   <name> <x> <y> <z>
 *   spin   <name> <deg>          (y rotation, degrees)
 *   # comment to end of line
 *
 * Objects declared between `group` and `end` become children of that group.
 */

const COMMANDS = ['box', 'sphere', 'group', 'end', 'move', 'spin'];
const ARITY = { box: 4, sphere: 2, group: 1, end: 0, move: 4, spin: 2 };

function makeNode(type, name = null) {
  return {
    type,
    name,
    position: [0, 0, 0],
    rotationDeg: 0,
    children: type === 'group' ? [] : undefined,
  };
}

function parseNumber(token) {
  if (!/^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(token.value)) return null;
  const n = Number(token.value);
  return Number.isFinite(n) ? n : null;
}

function collectNumbers(args, cmd, line, errors) {
  const nums = [];
  for (const tok of args) {
    const n = parseNumber(tok);
    if (n === null) {
      errors.push({ line, message: `non-numeric argument '${tok.value}' for '${cmd}'` });
      return null;
    }
    nums.push(n);
  }
  return nums;
}

/**
 * Compile scene-description source into a node tree whose nodes carry a
 * live Three.js scene graph in `.object` (THREE.Group / THREE.Mesh).
 *
 * @param {string} source
 * @returns {{ root: object, errors: Array<{line: number, message: string}> }}
 */
export function compileScene(source) {
  const lines = tokenize(source);
  const errors = [];
  const declared = new Map(); // name -> node
  const transforms = []; // deferred move/spin, applied after full parse

  const root = makeNode('group');
  const stack = [{ node: root, line: 0 }]; // innermost last

  for (const { number: line, tokens } of lines) {
    if (tokens.length === 0) continue; // blank or comment-only line
    const cmdTok = tokens[0];
    const cmd = cmdTok.value;

    if (!COMMANDS.includes(cmd)) {
      errors.push({ line, message: `unknown command '${cmd}'` });
      continue;
    }

    const args = tokens.slice(1);
    if (args.length !== ARITY[cmd]) {
      const expected = ARITY[cmd] === 0 ? 'no arguments' : `${ARITY[cmd] - 1} argument(s)`;
      errors.push({ line, message: `'${cmd}' expects ${expected}, got ${args.length}` });
      continue;
    }

    if (cmd === 'end') {
      if (stack.length === 1) {
        errors.push({ line, message: `'end' without matching 'group'` });
        continue;
      }
      stack.pop();
      continue;
    }

    const parent = stack[stack.length - 1].node;

    if (cmd === 'group') {
      const name = args[0].value;
      if (declared.has(name)) {
        errors.push({ line, message: `duplicate name '${name}'` });
        continue;
      }
      const node = makeNode('group', name);
      parent.children.push(node);
      declared.set(name, node);
      stack.push({ node, line });
      continue;
    }

    if (cmd === 'box' || cmd === 'sphere') {
      const name = args[0].value;
      if (declared.has(name)) {
        errors.push({ line, message: `duplicate name '${name}'` });
        continue;
      }
      const nums = collectNumbers(args.slice(1), cmd, line, errors);
      if (nums === null) continue;
      const node = makeNode(cmd, name);
      if (cmd === 'box') node.size = nums; // [w, h, d]
      else node.radius = nums[0];
      parent.children.push(node);
      declared.set(name, node);
      continue;
    }

    // move / spin: defer so forward references to later declarations work
    const name = args[0].value;
    const nums = collectNumbers(args.slice(1), cmd, line, errors);
    if (nums === null) continue;
    transforms.push({ kind: cmd, name, nums, line });
  }

  for (const open of stack.slice(1)) {
    errors.push({ line: open.line, message: `unclosed group '${open.node.name}' opened here` });
  }

  for (const t of transforms) {
    const node = declared.get(t.name);
    if (!node) {
      errors.push({ line: t.line, message: `${t.kind} on undeclared name '${t.name}'` });
      continue;
    }
    if (t.kind === 'move') node.position = t.nums;
    else node.rotationDeg = t.nums[0];
  }

  attachObjects(root);

  return { root, errors };
