/** Build the Three.js scene graph rooted at `node.object`. */
function attachObjects(node) {
  let object;
  switch (node.type) {
    case 'group':
      object = new THREE.Group();
      break;
    case 'box':
      object = new THREE.Mesh(new THREE.BoxGeometry(...node.size));
      break;
    case 'sphere':
      object = new THREE.Mesh(new THREE.SphereGeometry(node.radius, 32, 32));
      break;
