  object.position.set(...node.position);
  object.rotation.y = THREE.MathUtils.degToRad(node.rotationDeg);
  node.object = object;

  if (node.type === 'group') {
    for (const child of node.children) {
      attachObjects(child);
      object.add(child.object);
    }
  }
  return node;
}
