 * Round-trip pretty printer: turns a compiled node tree back into
 * equivalent scene-description source that recompiles isomorphically.
 *
 * Transforms are emitted as explicit `move` / `spin` statements only when
 * they differ from the defaults (position [0,0,0], rotation 0).
 */

function fmt(n) {
  return Number.isInteger(n) ? String(n) : String(Number(n.toFixed(6)));
}

function emitTransforms(node, pad, out) {
  const [x, y, z] = node.position;
  if (x !== 0 || y !== 0 || z !== 0) {
    out.push(`${pad}move ${node.name} ${fmt(x)} ${fmt(y)} ${fmt(z)}`);
  }
  if (node.rotationDeg !== 0) {
    out.push(`${pad}spin ${node.name} ${fmt(node.rotationDeg)}`);
  }
}

function emitNode(node, depth, out) {
  const pad = '  '.repeat(depth);
  if (node.type === 'group') {
    out.push(`${pad}group ${node.name}`);
    for (const child of node.children) emitNode(child, depth + 1, out);
    out.push(`${pad}end`);
  } else if (node.type === 'box') {
    out.push(`${pad}box ${node.name} ${node.size.map(fmt).join(' ')}`);
    emitTransforms(node, pad, out);
  } else if (node.type === 'sphere') {
    out.push(`${pad}sphere ${node.name} ${fmt(node.radius)}`);
    emitTransforms(node, pad, out);
  } else {
    throw new Error(`prettyPrint: unknown node type '${node.type}'`);
  }
}

/**
 * @param {object} root - compiled root node (or any group node)
 * @returns {string} equivalent DSL source (ends with a newline)
 */
export function prettyPrint(root) {
  const out = [];
  if (root.name !== null && root.name !== undefined) {
    // A named group passed directly: wrap it explicitly.
    emitNode(root, 0, out);
  } else {
    for (const child of root.children) emitNode(child, 0, out);
  }
  return out.join('\n') + '\n';
}
