// 12-line inline sample: a snowman inside a 'yard' group.
const SNOWMAN = [
  '# snowman in a yard',            // 1
  'group yard',                     // 2
  'sphere body 1',                  // 3
  'sphere head 0.7',                // 4
  'move head 0 1.5 0',              // 5
  'sphere button 0.1',              // 6
  'move button 0 0.4 0.95',         // 7
  'box arm 0.9 0.12 0.12',          // 8
  'move arm 1.0 1.4 0',             // 9
  'spin arm 25',                    // 10
  'end',                            // 11
  '',                               // 12 (trailing blank line)
].join('\n');

/** Strip a compiled tree down to plain data for structural comparison. */
function plain(node) {
  return {
    type: node.type,
    name: node.name,
    ...(node.type === 'box' ? { size: node.size } : {}),
    ...(node.type === 'sphere' ? { radius: node.radius } : {}),
    position: node.position,
    rotationDeg: node.rotationDeg,
    children: node.type === 'group' ? node.children.map(plain) : [],
  };
}

function findNode(node, name) {
  if (node.name === name) return node;
  for (const c of node.children ?? []) {
    const hit = findNode(c, name);
    if (hit) return hit;
  }
  return null;
}

describe('snowman sample', () => {
  const { root, errors } = compileScene(SNOWMAN);

  it('compiles without errors', () => {
    expect(errors).toEqual([]);
  });

  it('builds the exact hierarchy', () => {
    expect(root.type).toBe('group');
    expect(root.name).toBeNull();
    expect(root.children).toHaveLength(1);
    const yard = root.children[0];
    expect(yard.type).toBe('group');
    expect(yard.name).toBe('yard');
    expect(yard.children.map((c) => [c.type, c.name])).toEqual([
      ['sphere', 'body'],
      ['sphere', 'head'],
      ['sphere', 'button'],
      ['box', 'arm'],
    ]);
  });

  it('exposes the Three.js scene graph with exact dimensions', () => {
    const yard = root.children[0];
    // yard is an empty-positioned THREE.Group containing all four meshes
    expect(yard.object.isGroup).toBe(true);
    expect(yard.object.position.x).toBe(0);
    expect(yard.object.position.y).toBe(0);
    expect(yard.object.position.z).toBe(0);
    expect(yard.object.children).toHaveLength(4);

    const body = findNode(root, 'body');
    expect(body.object.geometry.parameters.radius).toBe(1);

    const head = findNode(root, 'head');
    expect(head.object.geometry.parameters.radius).toBe(0.7);

    const button = findNode(root, 'button');
    expect(button.object.geometry.parameters.radius).toBe(0.1);

    const arm = findNode(root, 'arm');
    expect(arm.object.geometry.parameters.width).toBe(0.9);
    expect(arm.object.geometry.parameters.height).toBe(0.12);
    expect(arm.object.geometry.parameters.depth).toBe(0.12);
  });

  it('applies exact positions and y rotations', () => {
    const body = findNode(root, 'body');
    expect(body.position).toEqual([0, 0, 0]);
    expect(body.rotationDeg).toBe(0);

    const head = findNode(root, 'head');
    expect(head.position).toEqual([0, 1.5, 0]);
    expect(head.rotationDeg).toBe(0);

    const button = findNode(root, 'button');
    expect(button.position).toEqual([0, 0.4, 0.95]);
    expect(button.rotationDeg).toBe(0);

    const arm = findNode(root, 'arm');
    expect(arm.position).toEqual([1.0, 1.4, 0]);
    expect(arm.rotationDeg).toBe(25);
    // rotation lands on the Three.js object as radians around y
    expect(arm.object.rotation.y).toBeCloseTo((25 * Math.PI) / 180, 12);
  });
});

describe('lexical details', () => {
  it('ignores comments and blank lines', () => {
    const src = [
      '# header comment',
      '',
      '   ',
      'group g # trailing comment',
      '# box ghost 1 2 3',
      'sphere s 2 # radius two',
      'end',
      '',
    ].join('\n');
    const { root, errors } = compileScene(src);
    expect(errors).toEqual([]);
    const g = root.children[0];
    expect(g.name).toBe('g');
    expect(g.children.map((c) => c.name)).toEqual(['s']);
  });

  it('tracks line numbers past comments and blanks', () => {
    const src = [
      '# line 1',
      '',          // 2
      'bogus x',   // 3 <- unknown command here
    ].join('\n');
    const { errors } = compileScene(src);
    expect(errors).toHaveLength(1);
    expect(errors[0]).toMatchObject({ line: 3 });
  });

  it('lexer reports columns for tokens', async () => {
    const { tokenize } = await import('../src/lexer.js');
    const lines = tokenize('box b 1 2 3\n  sphere s 0.5');
    expect(lines[0].tokens[0]).toEqual({ value: 'box', line: 1, column: 1 });
    expect(lines[0].tokens[3]).toEqual({ value: '2', line: 1, column: 8 });
    expect(lines[1].tokens[0]).toEqual({ value: 'sphere', line: 2, column: 3 });
  });
});

describe('error reporting', () => {
  it('unknown command -> right line number', () => {
    const src = [
      'group g',     // 1
      'cone c 1',    // 2
      'end',         // 3
    ].join('\n');
    const { errors } = compileScene(src);
    expect(errors).toEqual([
      { line: 2, message: "unknown command 'cone'" },
    ]);
  });

  it('wrong arg count -> right line number', () => {
    const src = [
      'box b 1 2',        // 1 (needs 3 dims)
      'sphere s',         // 2 (needs radius)
      'move m 0 0',       // 3 (needs 3 coords)
    ].join('\n');
    const { errors } = compileScene(src);
    expect(errors.map((e) => e.line)).toEqual([1, 2, 3]);
  });

  it('non-numeric args -> right line number', () => {
    const src = [
      'sphere s abc',     // 1
      'box b 1 wide 3',   // 2
    ].join('\n');
    const { errors } = compileScene(src);
    expect(errors).toHaveLength(2);
    expect(errors[0].line).toBe(1);
    expect(errors[0].message).toContain("non-numeric argument 'abc'");
    expect(errors[1].line).toBe(2);
    expect(errors[1].message).toContain("non-numeric argument 'wide'");
  });

  it('duplicate names -> right line number', () => {
    const src = [
      'sphere s 1',       // 1
      'box s 1 1 1',      // 2 duplicate
      'group g',          // 3
      'group g',          // 4 duplicate even nested
      'end',              // 5
    ].join('\n');
    const { errors } = compileScene(src);
    expect(errors.map((e) => e.line)).toEqual([2, 4]);
  });

  it('move/spin on undeclared names -> right line numbers', () => {
    const src = [
      'move ghost 1 2 3', // 1
      'spin phantom 45',  // 2
      'spin real 90',     // 3 ok
      'sphere real 1',    // 4 declared after use is still fine (deferred)
      'end',              // 5 stray end
    ].join('\n');
    const { errors, root } = compileScene(src);
    expect(errors).toEqual([
      { line: 1, message: "move on undeclared name 'ghost'" },
      { line: 2, message: "spin on undeclared name 'phantom'" },
      { line: 5, message: "'end' without matching 'group'" },
    ]);
    // deferred transform still landed on the later declaration
    expect(findNode(root, 'real').rotationDeg).toBe(90);
  });

  it('unclosed groups at EOF -> line of each unclosed group', () => {
    const src = [
      'group outer',  // 1
      'sphere s 1',   // 2
      'group inner',  // 3
      'box b 1 1 1',  // 4
    ].join('\n');
    const { errors } = compileScene(src);
    expect(errors).toEqual([
      { line: 1, message: "unclosed group 'outer' opened here" },
      { line: 3, message: "unclosed group 'inner' opened here" },
    ]);
  });

  it('no partial corruption: errored compiles leave a usable root', () => {
    const src = [
      'wat !',            // 1 unknown command
      'group yard',       // 2
      'sphere s xyz',     // 3 non-numeric
      'box b 1 2',        // 4 wrong arg count
      'sphere good 2',    // 5 fine
      'move missing 0 0 0', // 6 undeclared
      'yard 5',           // 7 unknown command (duplicate group skipped earlier)
      // no end -> 8th error: unclosed group
    ].join('\n');
    const { root, errors } = compileScene(src);
    // every expected error present, none spurious
    expect(errors.map((e) => e.line)).toEqual([1, 3, 4, 6, 8 - 1 + 1 === 8 ? 8 : 8]);
    // root is still a well-formed, traversable tree holding the valid nodes
    const yard = findNode(root, 'yard');
    expect(yard).not.toBeNull();
    expect(yard.children.map((c) => c.name)).toEqual(['good']);
    expect(findNode(root, 'good').object.geometry.parameters.radius).toBe(2);
    // the whole tree can be pretty-printed despite errors
    expect(() => prettyPrint(root)).not.toThrow();
  });
});

describe('prettyPrint round trip', () => {
  it('re-emits equivalent source that recompiles to an isomorphic tree', () => {
    const first = compileScene(SNOWMAN);
    expect(first.errors).toEqual([]);
    const printed = prettyPrint(first.root);

    // source must be syntactically equivalent to the original semantics
    expect(printed.split('\n').filter(Boolean)).toEqual([
      'group yard',
      'sphere body 1',
      'sphere head 0.7',
      'move head 0 1.5 0',
      'sphere button 0.1',
      'move button 0 0.4 0.95',
      'box arm 0.9 0.12 0.12',
      'move arm 1 1.4 0',
      'spin arm 25',
      'end',
    ]);

    const second = compileScene(printed);
    expect(second.errors).toEqual([]);
    expect(plain(second.root)).toEqual(plain(first.root));
  });

  it('is idempotent: printing twice changes nothing', () => {
    const first = compileScene(SNOWMAN);
    const once = prettyPrint(first.root);
    const twice = prettyPrint(compileScene(once).root);
    expect(twice).toBe(once);
  });
});
